<?php require_once __DIR__.'/../config/conexao.php';require_once __DIR__.'/../includes/funcoes.php';if($_SERVER['REQUEST_METHOD']!=='POST'||!validarCsrf(post('csrf'))){flash('erro','Formulário inválido.');redirect('contato.php');}$honeypot=trim((string)post('website'));if($honeypot!==''){flash('erro','Não foi possível enviar a mensagem.');redirect('contato.php');}$nome=trim((string)post('nome'));$email=strtolower(trim((string)post('email')));$assunto=trim((string)post('assunto'));$mensagem=trim((string)post('mensagem'));if(mb_strlen($nome)<3||mb_strlen($nome)>120||mb_strlen($email)>180||mb_strlen($assunto)>120||mb_strlen($mensagem)<1||mb_strlen($mensagem)>5000||!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('erro','Preencha os campos obrigatórios corretamente.');redirect('contato.php');}$pdo=getPDO();if(!$pdo){flash('info','Mensagem recebida no formulário. Configure o banco para registrar as mensagens.');redirect('contato.php');}try{$st=$pdo->prepare('INSERT INTO mensagens_contato(nome,email,assunto,mensagem) VALUES(?,?,?,?)');$st->execute([$nome,$email,$assunto,$mensagem]);flash('sucesso','Mensagem enviada. Em breve a Açaí Flow entrará em contato.');}catch(Throwable $e){flash('erro','Não foi possível registrar a mensagem.');}redirect('contato.php');
